contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target, uint _value, bytes memory _data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_target != address(c));
        require(address(this).balance >= _value);

        uint beforeTargetBalance = _target.balance;

        bool reverted;
        c.sendMoney(_target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterTargetBalance = _target.balance;

        assert(reverted ? afterTargetBalance == beforeTargetBalance : afterTargetBalance == beforeTargetBalance + _value);
    }

    receive() external payable {}
}

